function openResort(id,tab='overview'){detailResort=id;detailTab=tab;const r=resorts.find(r=>r.id===id),c=catalog[id];modal(`<div class="resortcover"><img src="${c.photos[0].file}" alt="${escapeText(c.photos[0].label)}"><div class="resortcovertext"><span>${c.city}</span><h2>${r.name}</h2><span class="glasspill">РЕАЛЬНОЕ МЕСТО · ФОТО ИЗ ОТКРЫТЫХ ИСТОЧНИКОВ</span></div></div><div class="detailtabs" role="tablist" aria-label="Разделы курорта">${[['overview','Обзор'],['slopes','Трассы'],['hotels','Отели'],['tickets','Билеты']].map(([k,t])=>`<button role="tab" aria-selected="${k===tab}" data-detail="${k}" class="${k===tab?'active':''}">${t}</button>`).join('')}</div><div class="detailbody" id="detailbody" role="tabpanel"></div>`);$('#modal').classList.add('resortdialog');$$('[data-detail]').forEach(b=>b.onclick=()=>{detailTab=b.dataset.detail;$$('[data-detail]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-selected',String(x===b))});paintDetail()});paintDetail();$('#modal').scrollTop=0}
function paintDetail(){const r=resorts.find(r=>r.id===detailResort),c=catalog[detailResort],body=$('#detailbody');if(detailTab==='overview'){body.innerHTML=`<p class="detailintro">${c.about}</p><div class="detailactions"><button class="primary" id="planstay">Спланировать поездку</button>${link(c.site,'Сайт курорта','outline outlink')}</div><div class="detailsection"><h3>Посмотри, прежде чем поехать</h3><div class="photostrip">${c.photos.map((p,i)=>`<button data-photo="${i}" aria-label="Открыть фото: ${escapeText(p.label)}"><img src="${p.file}" alt="${escapeText(p.label)}" loading="lazy"><span>${p.type}</span></button>`).join('')}</div><p class="detailnote">Архивные фотографии показывают место, а не текущие условия на склоне.</p></div><div class="detailservicegrid"><button id="detailhotels">Отели и проживание <span>↗</span></button><button id="detailrent">Прокат экипировки <span>↗</span></button><button id="detail3d">Почувствовать склон <span>↗</span></button><button id="detailpeople">Найти компанию <span>↗</span></button></div><p class="detailnote">Информация из открытых источников · проверка источников 25.10.2026. Партнёрский договор пока не заключён.</p>`;$('#planstay').onclick=()=>stayPlanner(detailResort);$('#detailhotels').onclick=()=>openResort(detailResort,'hotels');$('#detailrent').onclick=()=>{selectResort(detailResort);rental()};$('#detail3d').onclick=()=>{$('#modal').close();go('explore');$('.featuregrid').scrollIntoView({behavior:'smooth',block:'center'});toast('3D-концепт: условная модель, не точная карта курорта')};$('#detailpeople').onclick=()=>{$('#modal').close();go('crew')};$$('[data-photo]').forEach(b=>b.onclick=()=>photoViewer(detailResort,Number(b.dataset.photo)))}
else if(detailTab==='slopes'){body.innerHTML=`<h3>Узнай гору до первого спуска</h3><p>Официальная схема поможет изучить расположение трасс и подъёмников. Живой статус, закрытия и состояние снега уточняй у курорта.</p><div class="photostrip">${c.photos.filter(p=>p.type!=='Проживание').map(p=>`<img src="${p.file}" alt="${escapeText(p.label)}" loading="lazy">`).join('')}</div><div class="linkstack">${link(c.map,'Схема трасс и курорта')}${link(c.cameras,'Камеры на сайте источника')}</div><div class="noticebox"><strong>Официальная геометрия ещё не подключена</strong><p>Для точной карты ждём от оператора линии трасс, подъёмники, сложность и актуальные предупреждения. Наш 3D-концепт не используется для навигации.</p></div>`}
else if(detailTab==='hotels'){body.innerHTML=`<h3>Останься ещё на один день</h3><p>Реальные варианты и каталоги проживания. Наличие номеров и цена подтверждаются на стороне поставщика.</p><div class="hotelgrid">${c.hotels.map((h,i)=>`<article class="hotelcard"><img src="${h.photo}" alt="${escapeText(h.photoNote)}" loading="eager"><div><small>${h.photoNote}</small><h4>${h.name}</h4><p>${h.description}</p><button class="primary" data-planhotel="${i}">Выбрать даты</button>${link(h.url,'Сайт проживания')}</div></article>`).join('')}</div><p class="detailnote">Сейчас SnowWow сохраняет план, но не отправляет бронь и не принимает оплату.</p>`;$$('[data-planhotel]').forEach(b=>b.onclick=()=>stayPlanner(detailResort,Number(b.dataset.planhotel)))}
else{body.innerHTML=`<h3>Подъёмники и ски-пассы</h3><p>Выбери дату и проверь действующие тарифы у поставщика. Мы не показываем архивную цену как актуальную.</p><div class="linkstack">${link(c.tickets,'Билеты и тарифы у источника')}${link(c.rent,'Прокат и услуги у источника')}${link(c.site,'Официальная информация о направлении')}</div><div class="noticebox"><strong>Без выдуманной доступности</strong><p>Продажа внутри агрегатора появится после договора с поставщиком, подключения остатков, оплаты, чеков и возвратов. В этой версии переход ведёт на внешний сайт.</p></div>`}}
function photoViewer(id,index){const c=catalog[id],p=c.photos[index];lightboxIndex=index;modal(`<div class="lightbox"><img src="${p.file}" alt="${escapeText(p.label)}"><div class="lightboxbar"><button id="previousphoto" aria-label="Предыдущее фото">←</button><span>${index+1} / ${c.photos.length}</span><button id="nextphoto" aria-label="Следующее фото">→</button></div><h2>${p.label}</h2><p>Архивный вид. Не отражает состояние трасс сегодня.</p>${link(p.source,'Источник фотографии')}<button class="outline full" id="backresort">Вернуться к курорту</button><p class="detailnote">Материал сайта курорта для закрытого прототипа. Коммерческое разрешение не подтверждено.</p></div>`);$('#previousphoto').onclick=()=>photoViewer(id,(index-1+c.photos.length)%c.photos.length);$('#nextphoto').onclick=()=>photoViewer(id,(index+1)%c.photos.length);$('#backresort').onclick=()=>openResort(id)}
