function stayPlanner(id,hotelIndex=0){const c=catalog[id],r=resorts.find(r=>r.id===id),today=new Date(),tomorrow=new Date(today);tomorrow.setDate(today.getDate()+1);modal(`<span class="eyebrow">ТВОЯ ПОЕЗДКА · ${r.name}</span><h2>Просыпаться ближе к горам.</h2><p>Выбери проживание и даты. План останется на устройстве - это не подтверждённое бронирование.</p><form id="stayform" class="stayform"><label class="wide">Проживание<select id="stayhotel">${c.hotels.map((h,i)=>`<option value="${i}" ${i===hotelIndex?'selected':''}>${h.name}</option>`).join('')}</select></label><label>Заезд<input id="checkin" type="date" required min="${dateISO(today)}" value="${dateISO(today)}"></label><label>Выезд<input id="checkout" type="date" required min="${dateISO(tomorrow)}" value="${dateISO(tomorrow)}"></label><label>Взрослых<select id="guests">${[1,2,3,4,5,6].map(n=>`<option ${n===2?'selected':''}>${n}</option>`).join('')}</select></label><label>Номеров<select id="rooms">${[1,2,3,4].map(n=>`<option>${n}</option>`).join('')}</select></label><label class="wide plancheck"><input type="checkbox" id="needsrental">Добавить прокат в план поездки</label><p id="stayerror" class="formerror wide" role="alert"></p><button class="primary wide" type="submit">Сохранить план поездки</button></form><p class="detailnote">Персональные и платёжные данные не запрашиваются. Цена и наличие ещё не подключены.</p>`);$('#checkin').onchange=()=>{const d=new Date($('#checkin').value+'T12:00:00');d.setDate(d.getDate()+1);const min=dateISO(d);$('#checkout').min=min;if($('#checkout').value<= $('#checkin').value)$('#checkout').value=min};$('#stayform').onsubmit=e=>{e.preventDefault();if($('#checkout').value<=$('#checkin').value){$('#stayerror').textContent='Выезд должен быть позже заезда.';return}const h=c.hotels[Number($('#stayhotel').value)],draft={id:Date.now(),resortId:id,resort:r.name,hotel:h.name,providerUrl:h.url,checkin:$('#checkin').value,checkout:$('#checkout').value,guests:Number($('#guests').value),rooms:Number($('#rooms').value),rental:$('#needsrental').checked,status:'draft',createdAt:new Date().toISOString()};tripDrafts.unshift(draft);write('snow-trips',tripDrafts);tripSummary(draft)}}
function tripText(d){return `SnowWow / План поездки\nСтатус: черновик, поставщику не отправлен. Не является бронью.\nКурорт: ${d.resort}\nПроживание: ${d.hotel}\nЗаезд: ${d.checkin}\nВыезд: ${d.checkout}\nВзрослых: ${d.guests}. Номеров: ${d.rooms}.\nПрокат: ${d.rental?'нужно уточнить':'не добавлен'}.\nНаличие, цена, отмена и подтверждение: у поставщика.\n${d.providerUrl}\n`}
function tripSummary(d){modal(`<span class="eyebrow">ПЛАН СОХРАНЁН НА УСТРОЙСТВЕ</span><h2>Твои горы ближе.</h2><div class="tripreceipt"><h3>${escapeText(d.hotel)}</h3><p>${escapeText(d.resort)}</p><strong>${d.checkin} → ${d.checkout}</strong><p>${d.guests} взрослых · ${d.rooms} ном. ${d.rental?'· нужен прокат':''}</p><span class="draftbadge">Черновик · не отправлен</span></div><p>Следующий шаг - уточнить наличие и забронировать на сайте поставщика. Условия оплаты и отмены действуют по его правилам.</p>${link(d.providerUrl,'Перейти к бронированию у поставщика','primary outlink')}<button class="outline full" id="downloadtrip">Скачать план поездки</button><button class="outline full" id="alltrips">Мои планы поездок</button>`);$('#downloadtrip').onclick=()=>downloadText('SnowWow_trip.txt',tripText(d));$('#alltrips').onclick=showTrips}
function downloadText(name,text){const u=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function showTrips(){modal(`<span class="eyebrow">ПОЕЗДКИ БЕЗ СУЕТЫ</span><h2>Мои планы</h2><div class="triplist">${tripDrafts.length?tripDrafts.map(d=>`<article><div><strong>${escapeText(d.resort)}</strong><p>${escapeText(d.hotel)}</p><small>${d.checkin} → ${d.checkout}</small><span class="draftbadge">Черновик · не отправлен</span></div><button class="outline" data-trip="${d.id}">Открыть</button><button class="iconbtn" data-deletetrip="${d.id}" aria-label="Удалить план поездки">×</button></article>`).join(''):'<p>Выбери курорт и проживание - здесь появится твой первый план.</p>'}</div>`);$$('[data-trip]').forEach(b=>b.onclick=()=>tripSummary(tripDrafts.find(d=>String(d.id)===b.dataset.trip)));$$('[data-deletetrip]').forEach(b=>b.onclick=()=>{tripDrafts=tripDrafts.filter(d=>String(d.id)!==b.dataset.deletetrip);write('snow-trips',tripDrafts);showTrips()})}
